ALTER TABLE public.billing_accounts ADD COLUMN IF NOT EXISTS checkout_attempt_id uuid;
ALTER TABLE public.billing_accounts ADD COLUMN IF NOT EXISTS checkout_attempt_key text;
CREATE TABLE public.audio_usage (user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), requests integer NOT NULL DEFAULT 0);
GRANT ALL ON public.audio_usage TO service_role;
ALTER TABLE public.audio_usage ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.reserve_audio_request(p_user uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audio_usage(user_id,window_start,requests) VALUES(p_user,now(),1) ON CONFLICT(user_id) DO UPDATE SET window_start=CASE WHEN public.audio_usage.window_start<now()-interval '1 hour' THEN now() ELSE public.audio_usage.window_start END, requests=CASE WHEN public.audio_usage.window_start<now()-interval '1 hour' THEN 1 ELSE public.audio_usage.requests+1 END WHERE public.audio_usage.window_start<now()-interval '1 hour' OR public.audio_usage.requests<60; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.reserve_audio_request(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reserve_audio_request(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.begin_checkout_attempt(p_user uuid,p_env text,p_token uuid,p_key text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE attempt uuid; BEGIN UPDATE public.billing_accounts SET checkout_attempt_id=CASE WHEN checkout_attempt_key=p_key AND checkout_attempt_id IS NOT NULL THEN checkout_attempt_id ELSE gen_random_uuid() END,checkout_attempt_key=p_key,checkout_lock_until=now()+interval '3 minutes' WHERE user_id=p_user AND environment=p_env AND checkout_lock_token=p_token AND checkout_lock_until>now() AND NOT deleting RETURNING checkout_attempt_id INTO attempt; IF attempt IS NULL THEN RAISE EXCEPTION 'Checkout lease expired'; END IF; RETURN attempt; END $$;
REVOKE ALL ON FUNCTION public.begin_checkout_attempt(uuid,text,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.begin_checkout_attempt(uuid,text,uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.check_subscription_owner() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (OLD.user_id IS DISTINCT FROM NEW.user_id OR OLD.stripe_customer_id IS DISTINCT FROM NEW.stripe_customer_id OR OLD.environment IS DISTINCT FROM NEW.environment) THEN RAISE EXCEPTION 'Subscription ownership cannot change'; END IF; IF NOT EXISTS(SELECT 1 FROM public.billing_accounts WHERE user_id=NEW.user_id AND environment=NEW.environment AND customer_id=NEW.stripe_customer_id) THEN RAISE EXCEPTION 'Subscription customer mismatch'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_subscription_ownership BEFORE INSERT OR UPDATE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.check_subscription_owner();